func dailyTemperatures(_ t: [Int]) -> [Int] {
    var answer = [Int](repeating: 0, count: t.count)
    var stack: [Int] = []
    for i in t.indices {
        while let top = stack.last, t[top] < t[i] {
            answer[top] = i - top
            stack.removeLast()
        }
        stack.append(i)
    }
    return answer
}
